import time, mujoco, numpy as np

model_ref = mujoco.MjModel.from_xml_path('/app/model_ref.xml')
model = mujoco.MjModel.from_xml_path('/app/model.xml')


def simulate(model, seed=0):
    data = mujoco.MjData(model)
    nstep = int(2.0 / model.opt.timestep)
    rng = np.random.default_rng(seed)
    data.qpos += rng.normal(0,0.01,size=data.qpos.shape)
    mujoco.mj_forward(model, data)
    for _ in range(nstep):
        mujoco.mj_step(model, data)


def timing(model, n=10):
    times=[]
    for _ in range(n):
        seed = np.random.randint(0,10000)
        t0 = time.perf_counter()
        simulate(model, seed)
        t1 = time.perf_counter()
        times.append(t1-t0)
    return np.mean(times)

ref_time = timing(model_ref, n=5)
new_time = timing(model, n=5)
print('ref', ref_time, 'new', new_time, 'pct', new_time/ref_time)
